class Client {
    class Node {                         // private nested type
    public:
        int value() const;
    };
    friend class ClientAttorney;          // only the gatekeeper sees Node
    Node node_;
    void reset();                         // another private member
};

class ClientAttorney {
public:
    typedef Client::Node node_type;       // selected type, not all Client internals
private:
    static node_type& node(Client& c) { return c.node_; }
    static void reset(Client& c) { c.reset(); }
    friend class Inspector;               // only Inspector calls the private gate
};

class Inspector {
    void inspect(Client& c) {
        ClientAttorney::node_type& n = ClientAttorney::node(c);
        (void)n.value();
    }
};

template<class TClient>
class Attorney : public TClient {
public:
    Attorney(TClient& c) : client_(c) {}
private:
    TClient& client_;
};

class ClientAttorney : public Attorney<Client> {   // friend of Client
public:
    using Attorney<Client>::Attorney;
    using Client::privateMethod;      // selectively export
};

